// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }
    function testRegression_property() public {
        vm.deal(address(this), 20 ether);
        vm.warp(1000);
        (bool ok1,) = address(c).call{value: 10 ether}("");
        assertTrue(ok1);
        vm.warp(1001);
        (bool ok2,) = address(c).call{value: 10 ether}("");
        assertTrue(!ok2, "Second call should revert on reference");
    }
}
